#pragma once#pragma once#ifdef LISTXMLRSU_EXPORTS#define LISTXMLRSU_API Q_DECL_EXPORT        #else#define LISTXMLRSU_API Q_DECL_IMPORT        #endif#include <UniBuffer.h>//DECLARE_HANDLE(HXML);#define INVALID_HXML HXML(INVALID_UNI)//struct SItemXML  {  UINT  m_nCount ;// Количество параметров в SUniPara  UINT  m_nPlace ;// Положение  параметров в SUniPara  HXML  m_nParent;// Номер родителя  HXML  m_nСhild ;// Номер первого реб¸нка  HXML  m_nNext  ;// Следующий  в списке  HXML  m_nPrev  ;// Предыдущий в списке  HNAME m_nFree  ;// Свободный параметр (SUniName)  UINT  m_nData  ;// Для ссылок на внешние данные  };//class LISTXMLRSU_API CListXML  {  static char ms_chVer;  //  // Содержит пары - имя = value  struct LISTXMLRSU_API SUniPara : public SUniBuffer    {    struct SLocal {HNAME m_nName,m_nValue;};    SUniPara(SUniName& rName)      :SUniBuffer(sizeof(SLocal)), name(rName){};    //    const char* Name(HPARA n)      {      SLocal* local = (SLocal*)m_szBuffer;      return name.Name(local[UINT(n)].m_nName);      }    const char* Value(HPARA n)      {      SLocal* local = (SLocal*)m_szBuffer;      return name.Name(local[UINT(n)].m_nValue);      }    bool Add ( const char* pName, const char* pValue, SUniChar& uni, UINT nCode );    private:    SUniName& name;    };  //  // Содержит XML-пары - имя = value  struct LISTXMLRSU_API SUniItem : public SUniBuffer    {    SUniItem(SUniPara& rPara)    : SUniBuffer(sizeof(SItemXML)){};    };  //  public:    CListXML();    virtual ~CListXML();    UINT Load( const char* pszFile );    UINT Read( const char* pszFile, const char* pszBin = NULL );    void Test( const char* pszFile );    void Save( const char* pszFile, _WIN32_FILE_ATTRIBUTE_DATA& attr );    //    SItemXML& Item( HXML n )      {      SItemXML* local = (SItemXML*)mItem.m_szBuffer;      return local[int(n)];      }    const char* Name( HXML n, UINT m = 0)      {      SItemXML* local = (SItemXML*)mItem.m_szBuffer;      return mPara.Name(HPARA(local[UINT(n)].m_nPlace+m));      }    const char* Value( HXML n, UINT m = 0)      {      SItemXML* local = (SItemXML*)mItem.m_szBuffer;      return mPara.Value(HPARA(local[UINT(n)].m_nPlace+m));      }    const char* Param( HXML nItem, const char* name = NULL )      {      SItemXML& item = Item( nItem );      if ( name == NULL )        return mName.Name(item.m_nFree);      //      for ( UINT n = 1; n < item.m_nCount; n++ )        {        const char* item  = Name( nItem, n );        if ( lstrcmpi( item, name ) == 0 )          return Value( nItem, n );        }      return NULL;      }    //    HXML FindItem ( HXML nParent, const char* _name );    HXML NextItem ( HXML nCurent, const char* _name );    HXML NextItem ( HXML nCurent );    UINT CountItem( HXML nParent, const char* _name );    HXML IsItems  ( HXML nParent, const char* _name, UINT nCount = 1 );    UINT CountAll ()      {      return mItem.Count();      }    //  private:    void ClearAll();    //    bool Binary( const char* pszFile, const char* pszBin, _WIN32_FILE_ATTRIBUTE_DATA& attr, char* pszFullBin );    UINT Parser( char*& ptr, HXML nParent, struct STegScn*& scn, int& nCount, SUniChar& uni );    void Test( HFILE hFile, HXML nFirst, int nLevel );    UINT TestFormat(HXML nFirst);    //    SUniItem mItem;    SUniPara mPara;    SUniName mName;// Буфер отсортированных текстовых строк    SUniChar mChar;// Буфер текстовых строк    char* m_buffALL;    UINT m_nCode;  };